import{_ as t,o as i,c as s,a2 as o}from"./chunks/framework.C-si7TFR.js";const g=JSON.parse('{"title":"Redis Trigger","description":"Trigger workflow by listening to Redis list push operations (LPUSH/RPUSH). Supports real-time message-driven workflows.","frontmatter":{"title":"Redis Trigger","description":"Trigger workflow by listening to Redis list push operations (LPUSH/RPUSH). Supports real-time message-driven workflows.","meta":[{"name":"keywords","content":"Redis, Trigger, LPUSH, RPUSH, List, Message Queue, Low-code, AI Workflow, Process Engine"}]},"headers":[],"relativePath":"trigger_redis.md","filePath":"trigger_redis.md"}'),r={name:"trigger_redis.md"};function a(d,e,n,l,h,p){return i(),s("div",null,[...e[0]||(e[0]=[o(`<h2 id="redis-trigger" tabindex="-1">Redis Trigger <a class="header-anchor" href="#redis-trigger" aria-label="Permalink to &quot;Redis Trigger&quot;">​</a></h2><p>Trigger the workflow by listening for new items pushed to a Redis list. When data is pushed to the specified Redis list key via <code>LPUSH</code> or <code>RPUSH</code>, the workflow is automatically executed. This is useful for building message-driven workflows, task queues, and real-time event processing.</p><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><ul><li><p><strong>Credential</strong> (Required): Select a Redis credential. You can create a Redis credential type in the <strong>App Development &gt; Credential</strong> section with the following configuration:</p><ul><li><strong>Host</strong>: The Redis server address.</li><li><strong>Port</strong>: The Redis server port (default: 6379).</li><li><strong>Auth</strong>: The Redis authentication password (optional).</li></ul></li><li><p><strong>Method</strong> (Required): The Redis list operation to listen for. Supported values:</p><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td>lpush</td><td>Triggered when data is pushed to the left of the list</td></tr><tr><td>rpush</td><td>Triggered when data is pushed to the right of the list</td></tr></tbody></table></li><li><p><strong>Select</strong> (Required): The Redis database index to use (0-based, must be ≥ 0).</p></li><li><p><strong>Key</strong> (Required): The Redis list key to monitor for new items.</p></li></ul><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><p>Each time a new item is pushed to the specified Redis list, the workflow is triggered with the pushed value as output. The output is the parsed JSON content of the pushed data.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pushed-value&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><blockquote><p>The actual output format depends on the data pushed to the Redis list.</p></blockquote><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><ol><li>When the workflow is enabled, IOLinker connects to the Redis server and monitors the specified list key.</li><li>When a new item is pushed to the list (via <code>LPUSH</code> or <code>RPUSH</code> depending on the configured method), the item is consumed and the workflow is triggered.</li><li>Each pushed item triggers a separate workflow execution, with the item data available as the trigger output.</li><li>Items are consumed from the list (popped), so they will not trigger the workflow more than once.</li></ol>`,10)])])}const c=t(r,[["render",a]]);export{g as __pageData,c as default};
